writing.exampleCode:
use std::sync::mpsc;
use std::thread;

let (tx, rx) = mpsc::channel();

for id in 0..3 {
    let tx = tx.clone();
    thread::spawn(move || {
        tx.send(format!("worker {id}")).unwrap();
    });
}
drop(tx); // so the loop can end

for message in rx {
    println!("{message}");
}

